"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["48314"],{68941(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>s,contentTitle:()=>o,toc:()=>l,assets:()=>d});var i=JSON.parse('{"id":"identity/fundanalysisfarewell","title":"","description":"This notice is long overdue. Ceasing publication wasn\'t our original intention \u2014 we simply wanted to take a break. But a distributed periodical isn\'t something you can just stop and start at will. We needed to notify our subscribers and refund their prepaid subscriptions. The small editorial team drifted apart for a while, and everyone found their own new paths. The market was poor, there wasn\'t much meaningful work to do, and whatever we were doing didn\'t feel like it had much value. Eventually, we decided to shut down for good. From the first issue in March 2007 to the final issue in September 2011.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/identity/fundanalysisfarewell.md","sourceDirName":"identity","slug":"/identity/fundanalysisfarewell","permalink":"/en/identity/fundanalysisfarewell","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"fundanalysisfarewell","title":"","hide_table_of_contents":true,"sidebar_label":"Fund Analysis farewell letter"},"sidebar":"identitySidebar","previous":{"title":"He has gone wandering, and will return again (Fund Analysis)","permalink":"/en/identity/hewillbeback"},"next":{"title":"Floating memories: my three meetings with \\"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n\\" Li Biao","permalink":"/en/identity/3meets"}}'),a=n(74848),r=n(28453);let s={id:"fundanalysisfarewell",title:"",hide_table_of_contents:!0,sidebar_label:"Fund Analysis farewell letter"},o="Fund Analysis \u2014 Farewell Letter",d={},l=[];function h(e){let t={em:"em",h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"fund-analysis--farewell-letter",children:"Fund Analysis \u2014 Farewell Letter"})}),"\n",(0,a.jsx)(t.p,{children:"This notice is long overdue. Ceasing publication wasn't our original intention \u2014 we simply wanted to take a break. But a distributed periodical isn't something you can just stop and start at will. We needed to notify our subscribers and refund their prepaid subscriptions. The small editorial team drifted apart for a while, and everyone found their own new paths. The market was poor, there wasn't much meaningful work to do, and whatever we were doing didn't feel like it had much value. Eventually, we decided to shut down for good. From the first issue in March 2007 to the final issue in September 2011."}),"\n",(0,a.jsxs)(t.p,{children:['The original idea for the magazine came from discussions with Muzi (Wood Child). The actual operations were handed over to Director Wang, who had previously managed the distribution of the "Red Edition" of ',(0,a.jsx)(t.em,{children:"Securities Weekly"}),". In that small office, during breaks from market research, we hoped to offer fund investors (friends were always asking which fund to buy) some rational guidance for their investment choices \u2014 to provide careful analysis and research on the chaotic fund industry, so that people wouldn't have to blindly follow fund salespeople's pitches. They'd have something to reference. That's how we founded ",(0,a.jsx)(t.em,{children:"Fund Analysis"})," magazine."]}),"\n",(0,a.jsxs)(t.p,{children:["Muzi was responsible for the lead article in every issue, giving readers a striking and illuminating perspective. Before that, I'd been a bit worried whether his writing could appeal to both sophisticated and general readers. After reading a few pieces, I knew he was more than up to the task. At that time, I had no idea he had a blog with such an enormous following \u2014 he never mentioned it. A few days before each issue went to press, we'd exchange rough ideas, and then he'd send his manuscript over. Whenever a new issue was published, Muzi would always come by and pick up a few copies to distribute to friends around him. The issue published on April 19, 2008 \u2014 ",(0,a.jsx)(t.em,{children:'"A Purely Technical Analysis Outlook on the Market Ahead"'})," \u2014 was the last article he left us. He was very ill at the time and returned to Guangzhou for treatment. We kept hoping he'd come back. In October, what arrived instead was the devastating news that he was gone forever."]}),"\n",(0,a.jsx)(t.p,{children:"Carrying our memory of him and our love for the securities market, we kept going \u2014 stumbling along until last year. A magazine survives on advertising and distribution revenue, and we'd never really managed the business side properly. With the securities market in a sustained slump and the entire fund industry posting losses, there was nothing left worth analyzing. The question of whether to continue or stop tormented us for a long time, but in the end, we stopped. It's been nearly a year since we ceased publication. Coming back to this blog, I see quite a few friends still paying attention \u2014 though of course, most of them are here because of Muzi. Thank you, everyone! Our magazine has been out of print for almost a year now. I wanted to explain the situation and ask for your understanding. This platform will be preserved going forward. Thank you all!"})]})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>o});var i=n(96540);let a={},r=i.createContext(a);function s(e){let t=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(r.Provider,{value:t},e.children)}}}]);